import{_ as i,l as s,o as e,c as l,v as r,p as m,x as t,d as n,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Rowhammer","description":"","frontmatter":{"title":"Rowhammer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rowhammer.md","filePath":"cs/rowhammer.md","lastUpdated":1789023840000}'),c={name:"cs/rowhammer.md"};function d(p,a,A,B,_,C){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="rowhammer" tabindex="-1">Rowhammer <a class="header-anchor" href="#rowhammer" aria-label="Permalink to &quot;Rowhammer&quot;">​</a></h1><div class="epigraph"><p>对相邻 DRAM 行的高频激活会在受害行上积累漏电，刷新来不及则位翻转；协议与 ECC 按「随机 FIT」设计时，会被这种定向扰动打穿。</p><footer>—— 据 Kim et al., Flipping Bits in Memory Without Accessing Them, ISCA 2014 整理</footer></div><p><a href="/cs/meltdown-kpti">上一课</a> 仍在 CPU 推测与页表。<a href="/cs/dram-refresh">DRAM 刷新</a> 假定干扰是均匀的。<a href="/cs/mttf-redundancy">MTTF</a> 的 ECC 对付稀疏随机翻转。本课不提供如何对准受害行的程序。缺口是 <strong>Rowhammer：激活干扰作为微结构/器件现象，以及刷新与隔离行等缓解。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM 阵列密，激活一行会在邻行耦合。若某行被反复打开（cache 缺失或显式 flush 使访问到达 DRAM），邻行电荷掉到阈值以下。缺口不是 <a href="/cs/mesi-protocol">MESI</a> 错了——内存控制器按合法命令在工作——而是<strong>器件层让「合法高频访问」变成对邻行的写。</strong></p><p><span class="marginnote">Kim 等在 2014 年公开此现象。缓解包括提高刷新率、TRR（追踪行刷新）、隔离行、ECC 升级。没有一种在所有代际上免费且完美。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>微结构视角：LLC 与预取决定哪些行真正打到 DRAM；行缓冲策略影响激活频率。系统：内存控制器检测异常激活模式则对邻行额外刷新。OS：降低敏感页与攻击者页的物理邻接（有限）。本课不描述如何绕过 cache 去锤某一物理行。</p>',8)),(e(),m(E,null,{default:t(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E9%AB%98%E9%A2%91%E6%BF%80%E6%B4%BB%E8%A1%8C%20A%22%5D%20--%3E%20COUP%5B%22%E9%82%BB%E8%A1%8C%E6%BC%8F%E7%94%B5%22%5D%0A%20%20COUP%20--%3E%20REF%5B%22%E5%88%B7%E6%96%B0%E7%AA%97%E5%8F%A3%E5%86%85%E6%9C%AA%E6%81%A2%E5%A4%8D%22%5D%0A%20%20REF%20--%3E%20BIT%5B%22%E5%8F%97%E5%AE%B3%E8%A1%8C%E4%BD%8D%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20MIT%5B%22TRR%20%2F%20%E6%8F%90%E9%AB%98%E5%88%B7%E6%96%B0%20%2F%20ECC%22%5D%20--%3E%20MIT2%5B%22%E9%99%8D%E4%BD%8E%E7%BF%BB%E8%BD%AC%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 Spectre：不需要预测器；需要的是物理邻接与激活。ECC 可能把翻转变成可检测错误，双比特以上仍可能漏。这把「正确性」从 ISA 扩展到器件。最后一课缓存侧信道回到 SRAM 时序，不依赖 DRAM 翻转。</p><p>刷新率加倍直接打带宽与功耗，是粗暴但明确的 MTTF 旋钮。TRR 试图只刷新「被打的邻居」，实现细节各代不同，教学上只需：内存控制器必须把激活历史当成可靠性输入，而不只是时序状态机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估具体芯片是否仍可被诱导翻转。也不把云厂商的专有缓解当定理。Prime+Probe 是缓存占用编码，与 Rowhammer 正交：一个读时序，一个写邻居电荷。</p><p>后课默认：DRAM 命令流有物理副作用。SRAM cache 的命中/缺失时序是更经典的侧信道介质。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rowhammer 是合法激活对邻行的电荷干扰，超出随机 FIT 模型。</li><li>缓解在刷新策略与行追踪，有功耗与带宽税。</li><li>缓存占用时序是下一课 Prime+Probe。</li><li>出处：Kim et al., <em>ISCA</em>, 2014。</li></ul>',8))])}const R=i(c,[["render",d]]);export{f as __pageData,R as default};
